#include <iostream>
using namespace std;

bool isLucky(int x) {
    while (x > 0) {
        int digit = x % 10;
        if (digit != 4 && digit != 7) return false;
        x /= 10;
    }
    return true;
}

int main() {
    int n;
    cin >> n;

    for (int i = 1; i <= n; ++i) {
        if (n % i == 0 && isLucky(i)) {
            cout << "YES\n";
            return 0;
        }
    }

    cout << "NO\n";
    return 0;
}

